class Camera:
    def __init__(self, width, height, screen_w, screen_h):
        self.camera = pygame.Rect(0, 0, width, height)
        self.width = width
        self.height = height
        self.screen_w = screen_w
        self.screen_h = screen_h

    def apply(self, entity):
        return entity.rect.move(self.camera.topleft)
        
    def apply_rect(self, rect):
        # Applies offset without a full entity object (for logic rectangles)
        return rect.move(self.camera.topleft)

    def update(self, target):
        desired_x = -target.rect.centerx + int(self.screen_w / 2)
        # Smooth camera glide
        self.camera.x += (desired_x - self.camera.x) * 0.1
        self.camera.y = 0 
        
        # Keep camera inside bounds
        self.camera.x = min(0, self.camera.x)  
        max_scroll = max(0, self.width - self.screen_w)
        self.camera.x = max(-max_scroll, self.camera.x)  

class Projectile(pygame.sprite.Sprite):
    def __init__(self, x, y, facing_right):
        super().__init__()
        self.image = pygame.Surface((35, 12), pygame.SRCALPHA)
        self.image.fill((100, 200, 255, 200)) # Glowing blue blast
        self.rect = self.image.get_rect(center=(x, y))
        self.speed = 12
        self.facing_right = facing_right

    def update(self):
        if self.facing_right:
            self.rect.x += self.speed
        else:
            self.rect.x -= self.speed

class Player(pygame.sprite.Sprite):
    def __init__(self, floor_y):
        super().__init__()
        self.floor_y = floor_y
        self.walk_frames = self.load_frames(WALK_FILE, 5, 5)
        self.idle_frames = self.load_frames(IDLE_FILE, 5, 5)

        self.current_frames = self.idle_frames
        self.frame_index = 0
        self.image = self.current_frames[self.frame_index]
        self.rect = self.image.get_rect(midbottom=(400, self.floor_y))
        
        self.walk_speed = 5    
        self.run_speed = 9     
        self.speed = self.walk_speed 
        
        self.facing_right = True
        self.is_moving = False
        self.is_running = False 
        
        self.last_update = pygame.time.get_ticks()
        self.frame_duration = 1000 // 12
        self.hit_timer = 0

    def load_frames(self, filename, rows, cols):
        if not os.path.exists(filename):
            print(f"MISSING FILE: {filename}")
            safe = pygame.Surface((40, 40))
            safe.fill((0, 255, 0)) 
            return [safe]
        try:
            sheet = pygame.image.load(filename).convert_alpha()
            
            # Simple removal: anything very dark becomes transparent
            sheet.lock()
            for x in range(sheet.get_width()):
                for y in range(sheet.get_height()):
                    r, g, b, a = sheet.get_at((x, y))
                    if r <= 50 and g <= 50 and b <= 50:
                        sheet.set_at((x, y), (0, 0, 0, 0)) # Transparent background
            sheet.unlock()
            
            w = sheet.get_width() // cols
            h = sheet.get_height() // rows
            frames = []
            for r in range(rows):
                for c in range(cols):
                    original = sheet.subsurface(pygame.Rect(c * w, r * h, w, h))
                    scaled_w = int(w * 0.45)
                    scaled_h = int(h * 0.45)
                    scaled = pygame.transform.scale(original, (scaled_w, scaled_h))
                    frames.append(scaled)
            return frames
        except Exception as e:
            print(f"ERROR LOADING PLAYER: {e}")
            safe = pygame.Surface((40, 40))
            safe.fill((0, 255, 0)) 
            return [safe]

    def take_damage(self):
        # Triggers visual red tint indicator for 1 second
        self.hit_timer = pygame.time.get_ticks() + 1000

    def update_logic(self, map_width, game_state): # Pass game state to clear text boxes on movement
        keys = pygame.key.get_pressed()
        self.is_moving = False
        self.is_running = False
        
        if keys[pygame.K_LSHIFT] or keys[pygame.K_RSHIFT]:
            self.is_running = True
            self.speed = self.run_speed
        else:
            self.is_running = False
            self.speed = self.walk_speed
        
        # Horizontal Movement
        if keys[pygame.K_LEFT] or keys[pygame.K_a]:
            self.rect.x -= self.speed
            self.facing_right = False
            self.is_moving = True
            # Clearing any active bookshelf message on movement
            game_state['active_message'] = None
            
        elif keys[pygame.K_RIGHT] or keys[pygame.K_d]:
            self.rect.x += self.speed
            self.facing_right = True
            self.is_moving = True
            # Clearing any active bookshelf message on movement
            game_state['active_message'] = None

        # Keep player solidly within map bounds
        if self.rect.left < 0: self.rect.left = 0
        if self.rect.right > map_width: self.rect.right = map_width

    def animate(self):
        now = pygame.time.get_ticks()
        
        if self.is_moving:
            if self.state != "walk":
                self.state = "walk"
                self.current_frames = self.walk_frames
                self.frame_index = 0
            self.frame_duration = 1000 // 30 if self.is_running else 1000 // 16
        else:
            if self.state != "idle":
                self.state = "idle"
                self.current_frames = self.idle_frames
                self.frame_index = 0
            self.frame_duration = 1000 // 12

        if now - self.last_update > self.frame_duration:
            self.last_update = now
            self.frame_index = (self.frame_index + 1) % len(self.current_frames)
            
        raw_image = self.current_frames[self.frame_index]
        
        if not self.facing_right:
            self.image = pygame.transform.flip(raw_image, True, False)
        else:
            self.image = raw_image.copy() 

        # Red tint hit indicator
        if now < self.hit_timer:
            self.image.fill((255, 0, 0), special_flags=pygame.BLEND_RGB_ADD)

    def update(self, map_width, game_state):
        self.update_logic(map_width, game_state)
        self.animate()
        self.rect.midbottom = (self.rect.centerx, self.floor_y)


class Enemy(pygame.sprite.Sprite):
    def __init__(self, start_x, floor_y, target_width, target_height):
        super().__init__()
        
        self.enemy_w = int(target_width * 1.03)
        self.enemy_h = int(target_height * 1.03)
        
        # Nudge the enemy's feet slightly down to match player grounding exactly
        self.floor_y = floor_y + ENEMY_Y_OFFSET
        self.all_frames = self.load_frames(ENEMY_FILE, 8, 6)
        
        if len(self.all_frames) >= 48:
            # Asset has multiple cycles. Rows 1-4 are menace walk cycles. (Frames 0-23)
            self.chase_frames = self.all_frames[0:24]
            # Multi-blast attack is frames 30-47 (Rows 6-8)
            self.attack_frames = self.all_frames[30:48]
        else:
            self.chase_frames = self.all_frames
            self.attack_frames = self.all_frames

        self.state = "chase"
        self.current_frames = self.chase_frames
        self.frame_index = 0
        self.image = self.current_frames[self.frame_index]
        
        self.rect = self.image.get_rect(midbottom=(start_x, self.floor_y))

        # MENACING walk logic (Menacing Creep, notMove Spamming)
        self.speed = 3 
        self.facing_right = True
        
        self.last_update = pygame.time.get_ticks()
        self.frame_duration = 1000 // 8 
        # MENACING: Long attack cooldown, prevents Move Spamming
        self.attack_cooldown_duration = 4000 # 4 seconds between attacks
        self.attack_cooldown_timer = pygame.time.get_ticks() + 2000 # initial wait
        self.has_fired_blast = False

    def load_frames(self, filename, rows, cols):
        if not os.path.exists(filename):
            print(f"MISSING FILE: {filename}")
            surf = pygame.Surface((self.enemy_w, self.enemy_h))
            surf.fill((0, 255, 0)) 
            return [surf]
        try:
            sheet = pygame.image.load(filename).convert_alpha()
            sheet_w, sheet_h = sheet.get_size()
            
            # Grabbing the exact background color from the top-left (assuming it is background noise)
            bg_noise_color = sheet.get_at((0, 0))
            
            # --- THE ADVANCED SILHOUETTE FILTER ---
            sheet.lock()
            for x in range(sheet_w):
                for y in range(sheet_h):
                    color = sheet.get_at((x, y))
                    r, g, b = color.r, color.g, color.b
                    
                    # Mathematical distance from the background noise color
                    dist_to_bg = abs(r - bg_noise_color.r) + abs(g - bg_noise_color.g) + abs(b - bg_noise_color.b)
                    
                    # 1. Background Noise / Box removal (High tolerance ensures complete box death)
                    if dist_to_bg <= 80: 
                        sheet.set_at((x, y), (0, 0, 0, 0)) # Completely Invisible
                        
                    # 2. Glowing eyes/Glitches/Blasts
                    # If it is bright, leave it alone.
                    elif r > 100 or g > 100 or b > 100:
                        pass # Keep original detail
                        
                    # 3. Everything else MUST be the monster's core body.
                    # FORCE IT TO BE SOLID PURE OPAQUE BLACK.
                    else:
                        sheet.set_at((x, y), (0, 0, 0, 255)) # Pure solid black

            sheet.unlock()
            
            # Slice the cleaned sheet into frames
            w = sheet.get_width() // cols
            h = sheet.get_height() // rows
            frames = []
            for r in range(rows):
                for c in range(cols):
                    original_frame = sheet.subsurface(pygame.Rect(c * w, r * h, w, h))
                    scaled = pygame.transform.scale(original_frame, (self.enemy_w, self.enemy_h))
                    frames.append(scaled)
            return frames
            
        except Exception as e:
            print(f"ERROR LOADING ENEMY: {e}")
            surf = pygame.Surface((self.enemy_w, self.enemy_h))
            surf.fill((0, 255, 0)) 
            return [surf]

    def update(self, player, projectile_group):
        now = pygame.time.get_ticks()
        dist_x = player.rect.centerx - self.rect.centerx

        # MENACING walk logic state machine
        if self.state == "chase":
            self.frame_duration = 1000 // 8 # MENACING walk rate
            
            if abs(dist_x) > 180: # MENACING: must creep within range
                # Creep slowly toward player X coordinate
                if dist_x > 0:
                    self.rect.x += self.speed
                    self.facing_right = True
                else:
                    self.rect.x -= self.speed
                    self.facing_right = False
            else:
                # Target is close enough. Ready to attack?
                if now > self.attack_cooldown_timer:
                    # switch to full attack sequence (Pauses movement, SWITCHES FRAMES)
                    self.state = "attack"
                    self.frame_index = 0
                    self.current_frames = self.attack_frames
                    self.frame_duration = 1000 // 20 # Attack anim is faster
                    self.has_fired_blast = False
        
        elif self.state == "attack":
            # MENACING: Beast stands still during attack to build dread.
            # Fires blast from middle of sequence.
            if self.frame_index == 10 and not self.has_fired_blast:
                # Fire blast central from eyes
                blast = Projectile(self.rect.centerx, self.rect.centery, self.facing_right)
                projectile_group.add(blast)
                self.has_fired_blast = True

        # Run the animation loop
        if now - self.last_update > self.frame_duration:
            self.last_update = now
            self.frame_index += 1

            if self.frame_index >= len(self.current_frames):
                if self.state == "attack":
                    # --- MENACING PAUSE: ATTACK COOLDOWN INITIATED ---
                    # End of full multi-frame blast animation sequence.
                    self.state = "chase" # Return to Menace Chase walk
                    self.current_frames = self.chase_frames
                    # Locked out of attack for 4 seconds (MOVE SPAMMING PREVENTED)
                    self.attack_cooldown_timer = now + self.attack_cooldown_duration
                self.frame_index = 0

            raw_image = self.current_frames[self.frame_index]
            if not self.facing_right:
                self.image = pygame.transform.flip(raw_image, True, False)
            else:
                self.image = raw_image
                
        # Lock enemy strictly to its dynamic grounded floor line
        self.rect.midbottom = (self.rect.centerx, self.floor_y)

